#include <algorithm>
#include <cstdint>
#include "acl/acl.h"
#include "kernel_operator.h"
#include "lib/matmul_intf.h"
#include "kernel_tiling/kernel_tiling.h"
#include "tiling/platform/platform_ascendc.h"
#include "tiling/tiling_api.h"

using namespace AscendC;

namespace {

constexpr uint32_t kFp32BlockElements = 8;
constexpr uint32_t kMaxMTiles = 512;  // ceil(max M / 16), including fallback tiling
constexpr float kPaddingMin = -3.402823466e+38F;

struct BatchMatmulMaxSumParams {
    uint32_t batch;
    uint32_t m;
    uint32_t n;
    uint32_t k;
    uint32_t mTiles;
    uint32_t baseM;
    uint32_t baseN;
    uint32_t directOutput;
    uint32_t transposeX1;
    uint32_t transposeX2;
};

template <typename T>
using AType = matmul::MatmulType<AscendC::TPosition::GM, ::CubeFormat::ND, T, true>;

template <typename T>
using BType = matmul::MatmulType<AscendC::TPosition::GM, ::CubeFormat::ND, T, true>;

using CType = matmul::MatmulType<AscendC::TPosition::VECIN, ::CubeFormat::ND, float>;
using BiasType = matmul::MatmulType<AscendC::TPosition::GM, ::CubeFormat::ND, float>;

template <typename T>
class BatchMatmulMaxSumKernel {
public:
    __aicore__ inline BatchMatmulMaxSumKernel() {}

    __aicore__ inline void Init(
        GM_ADDR x1,
        GM_ADDR x2,
        GM_ADDR partial,
        GM_ADDR y,
        const BatchMatmulMaxSumParams &params,
        const TCubeTiling &tiling)
    {
        params_ = params;
        tiling_ = tiling;

        x1_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x1));
        x2_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x2));
        partial_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(partial));
        y_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y));

        pipe_.InitBuffer(mmOutputQueue_, 1, params_.baseM * params_.baseN * sizeof(float));
        pipe_.InitBuffer(rowMaxBuffer_, params_.baseM * sizeof(float));
        pipe_.InitBuffer(tileMaxQueue_, 1, params_.baseM * sizeof(float));
        pipe_.InitBuffer(reduceWorkspaceBuffer_, 32768);
        if (params_.directOutput == 0) {
            pipe_.InitBuffer(finalInputQueue_, 1, kMaxMTiles * sizeof(float));
            pipe_.InitBuffer(finalSumQueue_, 1, kFp32BlockElements * sizeof(float));
            pipe_.InitBuffer(finalWorkspaceBuffer_, 4096);
        }
    }

    __aicore__ inline void Process()
    {
        const uint32_t blockIdx = GetBlockIdx();
        const uint32_t blockCount = GetBlockNum();
        const uint32_t totalJobs = params_.batch * params_.mTiles;

        for (uint32_t job = blockIdx; job < totalJobs; job += blockCount) {
            ProcessJob(job);
        }
        matmul_.End();

        if (params_.directOutput == 0) {
            // All partials must be globally visible before any core starts the
            // fixed-order M reduction.  false selects Mix (AIC+AIV) sync.
            SyncAll<false>();
            FinalizeBatches(blockIdx, blockCount);
        }
    }

private:
    __aicore__ inline uint32_t Min(uint32_t lhs, uint32_t rhs) const
    {
        return lhs < rhs ? lhs : rhs;
    }

    __aicore__ inline void ProcessJob(uint32_t job)
    {
        const uint32_t batchIdx = job / params_.mTiles;
        const uint32_t mTileIdx = job - batchIdx * params_.mTiles;
        const uint32_t mStart = mTileIdx * params_.baseM;
        const uint32_t currentM = Min(params_.baseM, params_.m - mStart);

        const uint64_t x1BatchOffset =
            static_cast<uint64_t>(batchIdx) * params_.m * params_.k;
        const uint64_t x2BatchOffset =
            static_cast<uint64_t>(batchIdx) * params_.k * params_.n;
        const uint64_t x1TileOffset = params_.transposeX1 != 0 ? mStart :
            static_cast<uint64_t>(mStart) * params_.k;

        matmul_.SetOrgShape(params_.m, params_.n, params_.k);
        matmul_.SetSingleShape(currentM, params_.n, params_.k);
        matmul_.SetTensorA(x1_[x1BatchOffset + x1TileOffset], params_.transposeX1 != 0);
        matmul_.SetTensorB(x2_[x2BatchOffset], params_.transposeX2 != 0);

        LocalTensor<float> rowMax = rowMaxBuffer_.Get<float>();
        LocalTensor<float> tileMax = tileMaxQueue_.AllocTensor<float>();
        Duplicate(rowMax, kPaddingMin, params_.baseM);
        uint32_t nTileIdx = 0;
        while (matmul_.template Iterate<true>()) {
            LocalTensor<float> mmOutput = mmOutputQueue_.AllocTensor<float>();
            matmul_.template GetTensorC<true>(mmOutput, false, true);
            // GetTensorC is produced by Cube and consumed by Vector.  The
            // queue event is the documented cross-engine dependency.
            mmOutputQueue_.EnQue(mmOutput);
            LocalTensor<float> mmReady = mmOutputQueue_.DeQue<float>();

            // For a single scalar C tile, Max(N) and Sum(M) are identities.
            // Besides avoiding two reductions, this is a useful correctness
            // boundary: it validates Matmul independently of Vector reduce.
            if (params_.m == 1 && params_.n == 1) {
                DataCopyExtParams scalarCopy = {1, sizeof(float), 0, 0, 0};
                DataCopyPad(y_[batchIdx], mmReady, scalarCopy);
                mmOutputQueue_.FreeTensor(mmReady);
                ++nTileIdx;
                continue;
            }

            const uint32_t nStart = nTileIdx * params_.baseN;
            const uint32_t currentN = Min(params_.baseN, params_.n - nStart);
            // Continuous GetTensorC writes [baseM, baseN].  Keep that physical
            // row stride for AR reduction and neutralize only the invalid tail.
            // SetValue is deliberately used here: a vector Duplicate starting
            // at currentN would be illegal when that offset is not 32B aligned.
            if (currentN < params_.baseN) {
                for (uint32_t row = 0; row < currentM; ++row) {
                    for (uint32_t col = currentN; col < params_.baseN; ++col) {
                        mmReady.SetValue(row * params_.baseN + col, kPaddingMin);
                    }
                }
                PipeBarrier<PIPE_V>();
            }

            LocalTensor<uint8_t> reduceWorkspace = reduceWorkspaceBuffer_.Get<uint8_t>();
            uint32_t reduceShape[] = {currentM, params_.baseN};
            ReduceMax<float, Pattern::Reduce::AR, false>(
                tileMax, mmReady, reduceWorkspace, reduceShape, true);
            Max(rowMax, rowMax, tileMax, currentM);

            mmOutputQueue_.FreeTensor(mmReady);
            ++nTileIdx;
        }

        if (params_.m == 1 && params_.n == 1) {
            tileMaxQueue_.FreeTensor(tileMax);
            return;
        }

        LocalTensor<float> reduceWorkspace = reduceWorkspaceBuffer_.Get<float>();
        ReduceSum<float>(tileMax, rowMax, reduceWorkspace, currentM);

        DataCopyExtParams copyParams = {1, sizeof(float), 0, 0, 0};
        tileMaxQueue_.EnQue(tileMax);
        LocalTensor<float> outputReady = tileMaxQueue_.DeQue<float>();
        if (params_.directOutput != 0) {
            DataCopyPad(y_[batchIdx], outputReady, copyParams);
        } else {
            DataCopyPad(partial_[job], outputReady, copyParams);
        }
        tileMaxQueue_.FreeTensor(outputReady);
    }

    __aicore__ inline void FinalizeBatches(uint32_t blockIdx, uint32_t blockCount)
    {
        for (uint32_t batchIdx = blockIdx; batchIdx < params_.batch; batchIdx += blockCount) {
            LocalTensor<float> input = finalInputQueue_.AllocTensor<float>();
            DataCopyExtParams copyParams = {
                1, static_cast<uint32_t>(params_.mTiles * sizeof(float)), 0, 0, 0};
            DataCopyPadExtParams<float> padParams = {
                true,
                0,
                static_cast<uint8_t>(
                    (kFp32BlockElements - params_.mTiles % kFp32BlockElements) %
                    kFp32BlockElements),
                0.0F};
            DataCopyPad(input, partial_[batchIdx * params_.mTiles], copyParams, padParams);
            finalInputQueue_.EnQue(input);

            LocalTensor<float> ready = finalInputQueue_.DeQue<float>();
            LocalTensor<float> sum = finalSumQueue_.AllocTensor<float>();
            LocalTensor<float> workspace = finalWorkspaceBuffer_.Get<float>();
            ReduceSum<float>(sum, ready, workspace, params_.mTiles);

            DataCopyExtParams outputParams = {1, sizeof(float), 0, 0, 0};
            finalSumQueue_.EnQue(sum);
            LocalTensor<float> sumReady = finalSumQueue_.DeQue<float>();
            DataCopyPad(y_[batchIdx], sumReady, outputParams);
            finalSumQueue_.FreeTensor(sumReady);
            finalInputQueue_.FreeTensor(ready);
        }
    }

public:
    // Kept public because REGIST_MATMUL_OBJ must be expanded in the global
    // kernel entry, matching the supported Matmul initialization pattern.
    TPipe pipe_;
    TCubeTiling tiling_;
    matmul::Matmul<AType<T>, BType<T>, CType, BiasType> matmul_;

private:
    TQue<QuePosition::VECIN, 1> mmOutputQueue_;
    TQue<QuePosition::VECOUT, 1> tileMaxQueue_;
    TQue<QuePosition::VECIN, 1> finalInputQueue_;
    TQue<QuePosition::VECOUT, 1> finalSumQueue_;
    TBuf<AscendC::TPosition::VECCALC> rowMaxBuffer_;
    TBuf<AscendC::TPosition::VECCALC> reduceWorkspaceBuffer_;
    TBuf<AscendC::TPosition::VECCALC> finalWorkspaceBuffer_;

    GlobalTensor<T> x1_;
    GlobalTensor<T> x2_;
    GlobalTensor<float> partial_;
    GlobalTensor<float> y_;
    BatchMatmulMaxSumParams params_;
};

template <typename T>
__schedmode__(1) __global__ __mix__(1, 1) void batch_matmul_max_sum_kernel(
    GM_ADDR x1,
    GM_ADDR x2,
    GM_ADDR partial,
    GM_ADDR y,
    BatchMatmulMaxSumParams params,
    __kfc_workspace__ GM_ADDR systemWorkspace,
    TCubeTiling tiling)
{
    BatchMatmulMaxSumKernel<T> op;
    // In separated mode Matmul registration must precede InitBuffer calls.
    op.tiling_ = tiling;
    REGIST_MATMUL_OBJ(&op.pipe_, GetSysWorkSpacePtr(), op.matmul_, &op.tiling_);
    op.Init(x1, x2, partial, y, params, tiling);
    op.Process();
}

inline uint32_t ChooseBaseM(uint32_t m)
{
    if (m <= 16) {
        return 16;
    }
    if (m <= 32) {
        return 32;
    }
    return 64;
}

inline uint32_t ChooseBaseN(uint32_t n)
{
    if (n <= 16) {
        return 16;
    }
    if (n <= 32) {
        return 32;
    }
    if (n <= 64) {
        return 64;
    }
    return 128;
}

inline bool TryBuildTiling(
    TCubeTiling &tiling,
    const platform_ascendc::PlatformAscendC &platform,
    uint32_t m,
    uint32_t n,
    uint32_t k,
    uint32_t baseM,
    uint32_t baseN,
    int32_t dtype,
    bool transposeX1,
    bool transposeX2)
{
    matmul_tiling::MatmulApiTiling tilingApi(platform);
    const matmul_tiling::DataType inputType = dtype == 2 ?
        matmul_tiling::DataType::DT_BFLOAT16 : matmul_tiling::DataType::DT_FLOAT16;
    if (tilingApi.SetAType(
            matmul_tiling::TPosition::GM,
            matmul_tiling::CubeFormat::ND,
            inputType,
            transposeX1) != 0 ||
        tilingApi.SetBType(
            matmul_tiling::TPosition::GM,
            matmul_tiling::CubeFormat::ND,
            inputType,
            transposeX2) != 0 ||
        tilingApi.SetCType(
            matmul_tiling::TPosition::VECIN,
            matmul_tiling::CubeFormat::ND,
            matmul_tiling::DataType::DT_FLOAT) != 0 ||
        tilingApi.SetBiasType(
            matmul_tiling::TPosition::GM,
            matmul_tiling::CubeFormat::ND,
            matmul_tiling::DataType::DT_FLOAT) != 0 ||
        tilingApi.SetShape(m, n, k) != 0 ||
        tilingApi.SetOrgShape(m, n, k) != 0 ||
        tilingApi.SetFixSplit(baseM, baseN, -1) != 0 ||
        tilingApi.SetBufferSpace(-1, -1, -1) != 0 ||
        tilingApi.EnableBias(false) != 0) {
        return false;
    }
    return tilingApi.GetTiling(tiling) != -1;
}

inline bool BuildTiling(
    TCubeTiling &tiling,
    const platform_ascendc::PlatformAscendC &platform,
    uint32_t m,
    uint32_t n,
    uint32_t k,
    uint32_t &baseM,
    uint32_t &baseN,
    int32_t dtype,
    bool transposeX1,
    bool transposeX2)
{
    if (TryBuildTiling(
            tiling,
            platform,
            m,
            n,
            k,
            baseM,
            baseN,
            dtype,
            transposeX1,
            transposeX2)) {
        return true;
    }

    // Some legal shape/layout combinations cannot use the preferred split.
    // Retry with the smallest Cube-aligned tile instead of silently returning
    // without a kernel launch.  Subsequent host parameters are derived from
    // these updated values, so device tiling and reduction strides stay equal.
    baseM = 16;
    baseN = 16;
    return TryBuildTiling(
        tiling,
        platform,
        m,
        n,
        k,
        baseM,
        baseN,
        dtype,
        transposeX1,
        transposeX2);
}

}  // namespace

extern "C" void run_kernel(
    GM_ADDR x1,
    const TensorGroupInfo &info_x1,
    GM_ADDR x2,
    const TensorGroupInfo &info_x2,
    GM_ADDR y,
    const TensorGroupInfo &info_y,
    int64_t availableCoreNum,
    aclrtStream stream,
    bool transposeX1,
    bool transposeX2)
{
    (void)info_y;
    const int64_t *x1Shape = info_x1.tensors[0].shape;
    const int64_t *x2Shape = info_x2.tensors[0].shape;
    const uint32_t batch = static_cast<uint32_t>(x1Shape[0]);
    const uint32_t m = static_cast<uint32_t>(transposeX1 ? x1Shape[2] : x1Shape[1]);
    const uint32_t k = static_cast<uint32_t>(transposeX1 ? x1Shape[1] : x1Shape[2]);
    const uint32_t n = static_cast<uint32_t>(transposeX2 ? x2Shape[1] : x2Shape[2]);
    uint32_t baseM = ChooseBaseM(m);
    uint32_t baseN = ChooseBaseN(n);

    auto *platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    if (platform == nullptr) {
        return;
    }

    TCubeTiling tiling;
    if (!BuildTiling(
            tiling,
            *platform,
            m,
            n,
            k,
            baseM,
            baseN,
            info_x1.tensors[0].dtype,
            transposeX1,
            transposeX2)) {
        return;
    }

    const uint32_t mTiles = (m + baseM - 1) / baseM;
    const uint32_t totalJobs = batch * mTiles;
    const uint32_t coreCount = static_cast<uint32_t>(availableCoreNum);
    const bool directOutput = mTiles == 1;
    // SyncAll in the multi-tile path is a device-wide hard barrier.  Launch
    // every physical Cube/AIV pair so every participant reaches the barrier;
    // idle blocks simply skip ProcessJob and join the final reduction phase.
    const uint32_t blockCount = directOutput ? std::min(coreCount, totalJobs) : coreCount;

    const size_t systemWorkspaceBytes = platform->GetLibApiWorkSpaceSize();
    const size_t partialBytes = directOutput ? 0 :
        static_cast<size_t>(totalJobs) * sizeof(float);
    const size_t workspaceBytes = systemWorkspaceBytes + partialBytes;
    uint8_t *workspaceDevice = nullptr;
    if (aclrtMalloc(reinterpret_cast<void **>(&workspaceDevice), workspaceBytes, ACL_MEM_MALLOC_HUGE_FIRST) !=
        ACL_SUCCESS) {
        return;
    }
    uint8_t *partialDevice = workspaceDevice + systemWorkspaceBytes;

    BatchMatmulMaxSumParams params = {
        batch,
        m,
        n,
        k,
        mTiles,
        baseM,
        baseN,
        directOutput ? 1U : 0U,
        transposeX1 ? 1U : 0U,
        transposeX2 ? 1U : 0U};
    if (info_x1.tensors[0].dtype == 2) {
        batch_matmul_max_sum_kernel<bfloat16_t><<<blockCount, nullptr, stream>>>(
            x1, x2, partialDevice, y, params, workspaceDevice, tiling);
    } else {
        batch_matmul_max_sum_kernel<half><<<blockCount, nullptr, stream>>>(
            x1, x2, partialDevice, y, params, workspaceDevice, tiling);
    }

    // The template's caller synchronizes only after run_kernel returns.  The
    // temporary workspace therefore cannot be released until the kernel ends.
    if (aclrtSynchronizeStream(stream) == ACL_SUCCESS) {
        aclrtFree(workspaceDevice);
    }
}

